    pw.println("Fireball");
    pw.println("Heal");
    pw.printf("Power: %d%n", 100);
} catch (IOException e) {
    System.err.println("Error: " + e.getMessage());
}

try (BufferedReader br = new BufferedReader(new FileReader("spells.txt"))) {
    String line;
    while ((line = br.readLine()) != null) {
        System.out.println(line);
    }
} catch (IOException e) {
    System.err.println("Error: " + e.getMessage());
}

